import * as THREE from 'three';
import {OrbitControls} from './assets/OrbitControls.js';
const C={floor:0xe8e6dd,cream:0xf2f0e9,dark:0x2c3b39,green:0x5b7770,wood:0xb9a58a,coral:0xe07563,metal:0xa5ada9,blue:0x687f95};
export class LabScene{
 constructor(host,onSelect){this.host=host;this.onSelect=onSelect;this.labelEls=[];this.showLabels=true;this.showPath=true;this.showSafety=false;this.selected=null;this.root=new THREE.Scene();this.root.background=new THREE.Color(0xe6e5de);this.camera=new THREE.PerspectiveCamera(36,1,.1,100);this.camera.position.set(9.6,10.8,13.4);this.camera.lookAt(0,0,0);this.clock=0;
 try{this.renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});this.renderer.setPixelRatio(Math.min(devicePixelRatio,2));this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=THREE.PCFSoftShadowMap;this.renderer.outputColorSpace=THREE.SRGBColorSpace;this.renderer.toneMapping=THREE.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.15;host.appendChild(this.renderer.domElement);this.controls=new OrbitControls(this.camera,this.renderer.domElement);this.controls.target.set(0,.15,0);this.controls.enableDamping=true;this.controls.minDistance=7;this.controls.maxDistance=26;this.controls.maxPolarAngle=Math.PI/2-.08;this.controls.update();this.raycaster=new THREE.Raycaster();let down={x:0,y:0};host.addEventListener('pointerdown',e=>down={x:e.clientX,y:e.clientY});host.addEventListener('pointerup',e=>{if(Math.hypot(e.clientX-down.x,e.clientY-down.y)>5||e.target.tagName!=='CANVAS')return;const r=host.getBoundingClientRect();this.raycaster.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),this.camera);const hits=this.raycaster.intersectObjects(this.world.children,true);for(const hit of hits){let o=hit.object;while(o&&!o.userData.entity)o=o.parent;if(o){this.select(o.userData.entity);break;}}});new ResizeObserver(()=>this.resize()).observe(host);}catch(e){this.fallback=true;this.flat=document.createElement('div');this.flat.className='fallback-map';host.appendChild(this.flat);}
 this.root.add(new THREE.HemisphereLight(0xffffff,0x77776b,2.8));const sun=new THREE.DirectionalLight(0xfff8ec,3.5);sun.position.set(-4,12,6);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-8;sun.shadow.camera.right=8;sun.shadow.camera.top=7;sun.shadow.camera.bottom=-7;sun.shadow.normalBias=.035;this.root.add(sun);const fill=new THREE.DirectionalLight(0xf6fbff,1.2);fill.position.set(7,5,-4);this.root.add(fill);this.resize();}
 material(color,roughness=.75){return new THREE.MeshStandardMaterial({color,roughness,metalness:color===C.metal ? .3 : .05});}
 box(w,h,d,x,y,z,color,parent=this.world){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),this.material(color));o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
 cyl(r,h,x,y,z,color,parent=this.world,r2=r){const o=new THREE.Mesh(new THREE.CylinderGeometry(r,r2,h,24),this.material(color));o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
 sphere(r,x,y,z,color,parent){const o=new THREE.Mesh(new THREE.SphereGeometry(r,20,14),this.material(color));o.position.set(x,y,z);o.castShadow=true;parent.add(o);return o;}
 group(entity){const g=new THREE.Group();if(entity)g.userData.entity=entity;this.world.add(g);return g;}
 label(text,x,y,z,type=''){const el=document.createElement('div');el.className=`scene-label ${type}`;el.textContent=text;this.host.appendChild(el);this.labelEls.push({el,pos:new THREE.Vector3(x,y,z)});}
 clear(){if(this.world){this.root.remove(this.world);this.world.traverse(o=>{o.geometry?.dispose();if(o.material)Array.isArray(o.material)?o.material.forEach(m=>m.dispose()):o.material.dispose();});}this.labelEls.forEach(l=>l.el.remove());this.labelEls=[];this.world=new THREE.Group();this.root.add(this.world);}
 setEnvironment(env,target){this.env=env;this.target=target;this.clear();this.box(10.2,.2,7.2,0,-.13,0,C.cream);this.box(10,.025,7,0,-.015,0,C.floor);const grid=new THREE.GridHelper(10,40,0xc9cec5,0xd6d8cf);grid.position.y=.004;grid.scale.z=.7;this.world.add(grid);
 this.box(10,1.18,.12,0,.55,-3.48,C.cream);this.box(.12,1.18,7,-4.98,.55,0,C.cream);this.box(10,.07,.14,0,1.17,-3.48,C.wood);this.box(.14,.07,7,-4.98,1.17,0,C.wood);
 for(let i=0;i<5;i++)this.box(.8,.04,.03,-4+i*2,.03,3.42,C.coral);
 this.floorText(env.scene==='coffee'?'01  /  COFFEE LAB':'02  /  LOGISTICS LAB',0,2.88,4.2,.36);
 const dock=this.group({id:'dock',name:'训练起始位',type:'导航点',x:env.start.x,z:env.start.z});this.cyl(.45,.025,env.start.x,.018,env.start.z,C.dark,dock);this.cyl(.3,.028,env.start.x,.02,env.start.z,C.green,dock);
 if(env.scene==='coffee')this.coffee();else this.logistics();
 for(const o of env.obstacles.filter(o=>o.dynamic)){const g=this.group({...o,type:'可变障碍'});this.box(o.w,.06,o.d,o.x,.04,o.z,C.dark,g);this.box(o.w*.9,o.h,o.d*.9,o.x,o.h/2+.06,o.z,0xc1a576,g);this.box(o.w*.92,.12,.02,o.x,o.h*.55,o.z+o.d/2,0xece3c9,g);}
 this.safety=new THREE.Group();this.world.add(this.safety);for(const o of env.obstacles){const wire=new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.BoxGeometry(o.w+.56,o.h,o.d+.56)),new THREE.LineBasicMaterial({color:C.coral,transparent:true,opacity:.7}));wire.position.set(o.x,o.h/2,o.z);this.safety.add(wire);}this.safety.visible=this.showSafety;
 const targ=env.targets[target];if(targ){this.targetRing=this.cyl(.34,.016,targ.x,.015,targ.z,C.coral);const ring=new THREE.Mesh(new THREE.RingGeometry(.37,.41,48),new THREE.MeshBasicMaterial({color:C.coral,side:THREE.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.set(targ.x,.025,targ.z);this.world.add(ring);this.label(targ.name,targ.x,.12,targ.z,'target');}
 this.makeRobot();this.robot.position.set(env.start.x,0,env.start.z);this.payload=this.group({id:env.scene==='coffee'?'coffee_cup':'parcel_01',name:env.scene==='coffee'?'常温模拟杯':'轻量训练箱',type:'任务物体',x:env.object.x,z:env.object.z});if(env.scene==='coffee'){this.cyl(.09,.17,0,.06,0,C.cream,this.payload);this.cyl(.08,.007,0,.148,0,0x5b4235,this.payload);const h=new THREE.Mesh(new THREE.TorusGeometry(.066,.013,8,20),this.material(C.cream));h.position.set(.1,.08,0);this.payload.add(h);}else{this.box(.5,.35,.36,0,.15,0,0xbd986d,this.payload);this.box(.09,.005,.36,0,.328,0,0xe0d3b8,this.payload);this.box(.22,.12,.007,0,.16,.185,C.cream,this.payload);}this.payload.position.set(env.object.x,env.object.y,env.object.z);
 this.pathLine=new THREE.Group();this.world.add(this.pathLine);this.label('ROBOT 01 · 仿真',env.start.x,1.92,env.start.z,'robot');this.robotLabel=this.labelEls.at(-1);this.drawPath([]);}
 floorText(text,x,z,w,h){const canvas=document.createElement('canvas');canvas.width=1024;canvas.height=100;const ctx=canvas.getContext('2d');ctx.fillStyle='#85918a';ctx.font='500 42px Arial';ctx.textAlign='center';ctx.fillText(text,512,64);const texture=new THREE.CanvasTexture(canvas);const mesh=new THREE.Mesh(new THREE.PlaneGeometry(w,h),new THREE.MeshBasicMaterial({map:texture,transparent:true,depthWrite:false}));mesh.rotation.x=-Math.PI/2;mesh.position.set(x,.013,z);this.world.add(mesh);}
 coffee(){const g=this.group({id:'bar',name:'咖啡操作台',type:'固定设施',x:-2.85,z:-2.05});this.box(3.3,.94,1.15,-2.85,.47,-2.05,C.green,g);this.box(3.4,.09,1.25,-2.85,.99,-2.05,C.wood,g);for(let i=0;i<4;i++){this.box(.012,.76,.015,-4.1+i*.83,.48,-1.464,C.dark,g);this.box(.19,.027,.04,-3.9+i*.81,.7,-1.44,C.metal,g);}const machine=this.group({id:'coffee_machine',name:'模拟咖啡机',type:'按钮操作对象',x:-3.7,z:-2.15});this.box(.67,.58,.52,-3.65,1.32,-2.13,C.metal,machine);this.box(.54,.38,.03,-3.65,1.29,-1.85,C.dark,machine);this.box(.56,.05,.38,-3.65,1.04,-1.83,C.dark,machine);this.cyl(.04,.08,-3.65,1.37,-1.77,C.metal,machine);this.sphere(.026,-3.48,1.5,-1.826,C.coral,machine);this.cyl(.08,.24,-1.8,1.15,-2.16,C.cream);this.cyl(.06,.25,-1.8,1.38,-2.16,C.green);this.label('语义对象 · 咖啡操作台',-2.85,1.8,-2.4);
 this.kettle=this.group({id:'training_pitcher',name:'常温模拟液体壶',type:'预设操作道具',x:-2.2,z:-2.05});this.cyl(.115,.25,0,.12,0,C.metal,this.kettle);this.cyl(.12,.02,0,.26,0,C.dark,this.kettle);const spout=this.cyl(.036,.18,-.15,.22,0,C.metal,this.kettle,.018);spout.rotation.z=Math.PI/2;const handle=new THREE.Mesh(new THREE.TorusGeometry(.1,.02,8,20),this.material(C.dark));handle.position.set(.14,.15,0);this.kettle.add(handle);this.kettle.position.set(-2.2,1.05,-2.05);this.pourStream=this.cyl(.011,.35,-2.75,1.43,-1.7,0x967252);this.pourStream.visible=false;

 for(const [id,t] of Object.entries(this.env.targets).filter(([id])=>id!=='sofa')){const cx=2.35,cz=t.z;const table=this.group({id,name:t.name,type:'交付设施',x:cx,z:cz});this.box(1.35,.08,1.25,cx,.84,cz,C.wood,table);for(const a of [-.5,.5])for(const b of [-.45,.45])this.box(.06,.8,.06,cx+a,.4,cz+b,C.dark,table);for(const a of [-1,1]){this.box(.44,.065,.4,cx+.98,.47,cz+a*.45,C.green,table);this.box(.055,.5,.42,cx+1.17,.7,cz+a*.45,C.green,table);for(const b of [-.14,.14])this.box(.035,.45,.035,cx+.98+b,.23,cz+a*.45,C.dark,table);}}
 const sofa=this.group({id:'sofa',name:'沙发交付点',type:'固定设施',x:1.95,z:2.65});this.box(1.25,.07,.65,1.95,.51,2.65,C.wood,sofa);this.box(.7,.48,.4,1.95,.25,2.65,C.dark,sofa);this.box(1.8,.42,.72,3.6,.33,2.65,C.green);this.box(1.8,.6,.18,3.6,.68,3.02,C.green);for(const x of [2.75,4.45])this.box(.13,.48,.78,x,.51,2.65,C.green);this.plant(-4.35,0,.1);this.plant(4.15,0,-2.75);}
 logistics(){const truck=this.group({id:'truck',name:'配送车模拟货台',type:'取货设施',x:-3.15,z:-2.05});this.box(2.4,.2,1.15,-3.15,.7,-2.05,C.metal,truck);this.box(2.4,.42,.09,-3.15,.92,-2.58,C.green,truck);for(const x of [-3.95,-2.35])for(const z of [-2.6,-1.5]){const wheel=this.cyl(.21,.1,x,.25,z,C.dark,truck);wheel.rotation.x=Math.PI/2;}this.box(.7,.8,1.15,-4.1,1.08,-2.05,C.green,truck);this.box(.05,.34,.85,-3.725,1.18,-2.05,0x839d9c,truck);this.box(.4,.3,.4,-2.3,1.01,-2.1,C.wood,truck);this.label('取货区 · 配送车',-3,1.9,-2.25);
 const rack=this.group({id:'rack',name:'模块化快递柜',type:'入柜设施',x:3,z:-.5});for(const x of [2.3,3.7])for(const z of [-2.4,-1.12,.12,1.4])this.box(.055,2.1,.055,x,1.05,z,C.dark,rack);for(const y of [.35,.91,1.48,2.08])this.box(1.45,.065,3.85,3,y,-.5,C.green,rack);this.box(.055,1.75,3.85,3.7,1.22,-.5,C.green,rack);for(let i=0;i<3;i++){this.box(.45,.3,.5,3.1,1.665,-1.75+i*1.25,C.wood,rack);this.box(.06,.31,.505,3.1,1.665,-1.75+i*1.25,0xd4c2a2,rack);}this.label('目标区 · 模块化快递柜',3,2.5,-.5);const buffer=this.group({id:'buffer',name:'分拣缓冲台',type:'固定设施',x:-2.8,z:1.6});this.box(1.3,.09,1.2,-2.8,.75,1.6,C.wood,buffer);for(const x of [-3.35,-2.25])for(const z of [1.1,2.1])this.box(.055,.7,.055,x,.35,z,C.dark,buffer);this.box(.32,.28,.38,-2.8,.94,1.6,C.wood,buffer);}
 plant(x,y,z){this.cyl(.2,.34,x,y+.17,z,C.cream);for(let i=0;i<6;i++){const leaf=new THREE.Mesh(new THREE.SphereGeometry(.2,12,10),this.material(C.green));leaf.scale.set(.55,1.8,.6);leaf.position.set(x+Math.sin(i)*.12,y+.53+(i%2)*.15,z+Math.cos(i)*.12);leaf.rotation.z=Math.sin(i)*.4;this.world.add(leaf);}}
 makeRobot(){const r=this.group({id:'robot_01',name:'人形训练机器人',type:'运动学示意本体',x:this.env.start.x,z:this.env.start.z});this.robot=r;this.box(.39,.44,.25,0,1.15,0,C.cream,r);this.box(.3,.26,.015,0,1.18,.135,C.dark,r);this.box(.15,.03,.017,0,1.25,.148,C.coral,r);this.cyl(.09,.08,0,1.43,0,C.dark,r);this.sphere(.165,0,1.6,0,C.cream,r);this.box(.26,.085,.1,0,1.62,.12,C.dark,r);this.box(.14,.015,.016,0,1.63,.178,C.green,r);this.box(.31,.16,.24,0,.83,0,C.dark,r);this.legs=[];this.arms=[];
 for(const sign of [-1,1]){const leg=new THREE.Group();leg.position.set(sign*.125,.8,0);r.add(leg);this.sphere(.075,0,0,0,C.dark,leg);this.cyl(.065,.29,0,-.18,0,C.cream,leg);this.sphere(.07,0,-.36,0,C.dark,leg);this.cyl(.055,.28,0,-.53,0,C.cream,leg);this.box(.15,.08,.28,0,-.74,.055,C.dark,leg);this.legs.push(leg);const arm=new THREE.Group();arm.position.set(sign*.25,1.34,0);r.add(arm);this.sphere(.075,0,0,0,C.dark,arm);this.cyl(.047,.25,0,-.17,0,C.cream,arm);this.sphere(.054,0,-.31,0,C.dark,arm);this.cyl(.044,.23,0,-.45,0,C.cream,arm);this.box(.09,.12,.08,0,-.61,0,C.dark,arm);this.arms.push(arm);}}
 drawPath(path){if(!this.pathLine)return;this.pathLine.children.slice().forEach(o=>{this.pathLine.remove(o);o.geometry?.dispose();o.material?.dispose();});if(path?.length>1){const geo=new THREE.BufferGeometry().setFromPoints(path.map(p=>new THREE.Vector3(p.x,.04,p.z)));const line=new THREE.Line(geo,new THREE.LineDashedMaterial({color:0x52796c,dashSize:.15,gapSize:.075}));line.computeLineDistances();this.pathLine.add(line);for(let i=0;i<path.length;i+=4){const dot=new THREE.Mesh(new THREE.SphereGeometry(.025,8,6),this.material(C.green));dot.position.set(path[i].x,.045,path[i].z);this.pathLine.add(dot);}}this.pathLine.visible=this.showPath;}
 setLayers({labels,path,safety}){if(labels!==undefined)this.showLabels=labels;if(path!==undefined){this.showPath=path;if(this.pathLine)this.pathLine.visible=path;}if(safety!==undefined){this.showSafety=safety;if(this.safety)this.safety.visible=safety;}}
 select(entity){this.selected=entity;this.onSelect?.(entity);}
 setView(mode){if(!this.controls)return;this.camera.position.set(...(mode==='top'?[.01,18,.01]:mode==='robot'?[this.robot.position.x+3,3.2,this.robot.position.z+4]:[9.6,10.8,13.4]));this.controls.target.copy(mode==='robot'?this.robot.position.clone().add(new THREE.Vector3(0,.8,0)):new THREE.Vector3(0,.15,0));this.controls.update();}
 resize(){const w=this.host.clientWidth,h=this.host.clientHeight;if(w&&h&&this.renderer){this.camera.aspect=w/h;this.camera.updateProjectionMatrix();this.renderer.setSize(w,h,false);}}
 update(state,dt){if(!this.env)return;this.clock+=dt;const p=state.pos||{x:state.x,z:state.z},moving=state.status==='RUNNING'&&['approach','deliver','home'].includes(state.skills?.[state.index]);this.robot.position.set(p.x,0,p.z);this.robot.userData.entity.x=p.x;this.robot.userData.entity.z=p.z;this.robot.rotation.y=state.yaw||0;this.legs.forEach((l,i)=>l.rotation.x=moving?Math.sin(this.clock*9+i*Math.PI)*.3:0);this.arms.forEach((a,i)=>a.rotation.x=state.carried?-1.03:moving?Math.sin(this.clock*9+i*Math.PI)*-.18:['prepare','grasp','place'].includes(state.skills?.[state.index])?-.8:0);
 if(state.carried){const front=new THREE.Vector3(0,1.05,.43).applyAxisAngle(new THREE.Vector3(0,1,0),state.yaw||0);this.payload.position.set(p.x+front.x,front.y,p.z+front.z);}else if(state.placed){const q=this.env.targets[this.target].place;this.payload.position.set(q.x,q.y,q.z);}else {const q=this.env.object;this.payload.position.set(q.x,q.y,q.z);}this.robotLabel.pos.set(p.x,1.96,p.z);
 if(this.env.scene==='coffee'&&this.kettle){const preparing=(state.skills?.[state.index]==='prepare');const phase=preparing?(state.stepProgress??.5):0;const arc=Math.sin(phase*Math.PI);this.kettle.position.set(-2.2-arc*.24,1.05+arc*.38,-2.05+arc*.35);this.kettle.rotation.z=arc*.72;this.pourStream.visible=preparing&&phase>.27&&phase<.78;}

 if(this.fallback){this.drawFallback(p);return;}this.controls.update();const w=this.host.clientWidth,h=this.host.clientHeight;if(!w||!h)return;for(const l of this.labelEls){const v=l.pos.clone().project(this.camera);l.el.style.display=this.showLabels&&v.z<1&&Math.abs(v.x)<.95&&Math.abs(v.y)<.95?'block':'none';l.el.style.transform=`translate(-50%,-100%) translate(${(v.x+1)*w/2}px,${(-v.y+1)*h/2}px)`;}this.renderer.render(this.root,this.camera);}
 drawFallback(p){const x=v=>(v+5)*60,z=v=>(v+3.5)*60;this.flat.innerHTML=`<div class="fallback-note">WebGL 不可用 · 二维路径视图</div><svg viewBox="0 0 600 420"><rect width="600" height="420" fill="#e6e5de"/>${this.env.obstacles.map(o=>`<rect x="${x(o.x-o.w/2)}" y="${z(o.z-o.d/2)}" width="${o.w*60}" height="${o.d*60}" rx="3" fill="${o.dynamic?'#bea779':'#5b7770'}"/>`).join('')}<circle cx="${x(p.x)}" cy="${z(p.z)}" r="12" fill="#e07563"/><text x="${x(p.x)+18}" y="${z(p.z)+5}" font-size="13">机器人</text></svg>`;}
}
